do $$ declare r record; begin for r in select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('create_check_in','kleenest_map_check_in','verify_checkin','submit_restroom_observation','submit_restroom_observation_with_photo','record_location_observation','submit_amenity_observation','submit_location_quality_observation','create_review','toggle_review_like','record_review_amenity_feedback','report_review','reply_to_review','get_favorite_locations','my_favorite_locations') loop execute format('revoke execute on function %I.%I(%s) from anon',r.nspname,r.proname,r.args); execute format('grant execute on function %I.%I(%s) to authenticated',r.nspname,r.proname,r.args); end loop; end $$;
